WITH base AS (SELECT * FROM stores WHERE store_name IS NULL AND store_name LIKE 'Old%' AND LOWER(TRIM(store_name)) = 'old town'), StoresStats AS (SELECT MONTH(opened_date) AS opened_month, CASE WHEN sqft >= 12209 THEN 'high' WHEN sqft >= 4571 THEN 'mid' ELSE 'low' END AS sqft_bucket, MAX(opened_date) AS last_opened_date FROM base GROUP BY MONTH(opened_date), CASE WHEN sqft >= 12209 THEN 'high' WHEN sqft >= 4571 THEN 'mid' ELSE 'low' END) SELECT opened_month, sqft_bucket, last_opened_date FROM StoresStats
